-- Materi BRS-13 (Blok 13 Sistem Respirasi): 26 bahasan PDF dalam 5 kelompok.
-- Dibuat oleh prisma/brs13-materi.py; berkas PDF & gambar halaman sudah ada di storage server.
-- Aman dijalankan pada database kosong (semua INSERT bergantung pada Blok BRS-13 yang ada).

-- Topik lama yang masih terbit (contoh 'Bab 1') disembunyikan, riwayatnya tetap.
UPDATE Topic SET published = false WHERE categoryId = (SELECT id FROM Category WHERE code = 'BRS-13') AND published = true AND id NOT LIKE 'dea-brs13-%';
-- Deskripsi kelas bawaan menyebut kuis per Bab; diganti hanya bila belum diubah admin.
UPDATE Category SET description = 'Blok 13 tahap akademik (preklinik). 26 bahasan sistem respirasi dalam 5 bagian, dari struktur dan fisiologi hingga penyakit serta farmakologi respirasi. Bagian 1 (bahasan 1–5) gratis untuk akun terdaftar.' WHERE code = 'BRS-13' AND description LIKE 'Blok 13 tahap akademik (preklinik). Materi dibagi per Bab%';

INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-brs13-group-1', id, 'Dasar Struktur dan Perkembangan Sistem Respirasi', 'Bahasan 1–5. Gratis untuk semua akun terdaftar.', 1, true FROM Category WHERE code = 'BRS-13';
